cargo.preparationScript:
import {prepareValue} from "./program";
import {observeCargoPreparationSourceV1,observeCargoPreparationInputV1,observeCargoPreparationOutputV1,completeCargoPreparationObservationV1} from {CUSTODY};
import {appendFileSync,mkdirSync,readFileSync,writeFileSync} from "node:fs";
import {dirname,resolve} from "node:path";
appendFileSync(resolve(process.cwd(),"preparation-calls.jsonl"),JSON.stringify({command:process.argv.slice(2)})+"
");
if(process.argv[2]!=="prepare")throw Error("Unknown preparation command");
if(prepareValue!==7)throw Error("Unexpected routing preparation value");observeCargoPreparationSourceV1(import.meta.path);
const input=resolve(process.cwd(),"owned-input.txt");const bytes=readFileSync(input);const value=JSON.parse(bytes.toString("utf8"));observeCargoPreparationInputV1(input,"file",bytes);if(value!==7)throw Error("Unexpected current owner input");
for(const [path,content] of Object.entries({"Cargo.toml":"[package]
name="native-dependency-fixture"
version="0.1.0"
edition="2021"
[lib]
path="🦀️.rs"
[workspace]
members = [".", "generated"] 
exclude = []
[workspace.metadata.semio.repository]
schema-version = 1
exclude-patterns = []
owner-manifests = []
member-manifests = ["Cargo.toml", "generated/Cargo.toml"]

[dependencies]
generated-dependency = { path = "generated" }

[package.metadata.semio.preparation]
script="owned/📜️script.ts"
command=["prepare"]
","generated/Cargo.toml":"[package]
name="generated-dependency"
version="0.1.0"
edition="2021"
[lib]
path="lib.rs"
","generated/lib.rs":"pub fn generated() -> u32 { 7 }
"})){const target=resolve(process.cwd(),path);mkdirSync(dirname(target),{recursive:true});writeFileSync(target,content);observeCargoPreparationOutputV1(target,content);}
completeCargoPreparationObservationV1();
console.log("[DEBUG] actual owner preparation introduced the current generated dependency");

